import{_ as a,o as r,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"آلية الانفتاح التكنولوجي والمشاركة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0069-技术开放与共享机制.md","filePath":"ar/0069-技术开放与共享机制.md"}'),e={name:"ar/0069-技术开放与共享机制.md"};function i(o,t,h,n,s,_){return r(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="آلية-الانفتاح-التكنولوجي-والمشاركة" tabindex="-1">آلية الانفتاح التكنولوجي والمشاركة <a class="header-anchor" href="#آلية-الانفتاح-التكنولوجي-والمشاركة" aria-label="Permalink to &quot;آلية الانفتاح التكنولوجي والمشاركة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>69</td></tr><tr><td>الوحدة</td><td>الأنظمة التكنولوجية والطاقية</td></tr><tr><td>الكلمات المفتاحية</td><td>الانفتاح التكنولوجي، تبادل المعارف، قوانين مفتوحة المصدر، تعميم التكنولوجيا، مكافحة الاحتكار</td></tr></tbody></table><h2 id="أولاً-المفهوم-المحوري-للانفتاح-التكنولوجي" tabindex="-1">أولاً: المفهوم المحوري للانفتاح التكنولوجي <a class="header-anchor" href="#أولاً-المفهوم-المحوري-للانفتاح-التكنولوجي" aria-label="Permalink to &quot;أولاً: المفهوم المحوري للانفتاح التكنولوجي&quot;">​</a></h2><p>إن آلية الانفتاح التكنولوجي والمشاركة في حضارة التكافل المرساة هي التجسيد العملي للبرنامج الأساسي «الأكثر عملاً الأكثر أجراً؛ النمو الذاتي والتطور الذاتي؛ لكل فرد طريق؛ تقدم عشرة آلاف عرق معاً» في المجال التكنولوجي. ومفهومها المحوري: المعرفة التقنية، بوصفها نتاج التطور الجماعي للحضارة كلها، يجب أن تتقاسمها الحضارة كلها؛ والاحتكار التقني وحواجز المعرفة من بقايا النظام الافتراسي في المجال التكنولوجي، ويجب إزالتها بالتصميم المؤسسي.</p><p>لا يعني الانفتاح التكنولوجي إنكار إسهامات مطوري التكنولوجيا. بل على العكس، أسست الحضارة التكافلية آلية تحفيز تقنية قوامها «إسهامات قابلة للقياس ومنافع قابلة للتتبع»، تضمن أن ينال عمل المطورين مكافأة معقولة، وأن تعم منافع الإنجازات التقنية على جميع أشكال الحياة بأدنى عتبة. وجوهر هذه الآلية تحويل التكنولوجيا من «سلعة يحتكرها الأقلون» إلى «بنية تحتية تتقاسمها الحضارة كلها».</p><h2 id="ثانياً-نظام-الانفتاح-التقني-المتدرج" tabindex="-1">ثانياً: نظام الانفتاح التقني المتدرج <a class="header-anchor" href="#ثانياً-نظام-الانفتاح-التقني-المتدرج" aria-label="Permalink to &quot;ثانياً: نظام الانفتاح التقني المتدرج&quot;">​</a></h2><p>يُطبق الانفتاح التقني على درجات وفق مستوى الخطر ودرجة النضج:</p><table tabindex="0"><thead><tr><th>درجة الانفتاح</th><th>التقنيات المعنية</th><th>أسلوب الانفتاح</th><th>شروط الدخول</th></tr></thead><tbody><tr><td>انفتاح كامل</td><td>التقنيات الناضجة من مستويي R0 وR1</td><td>جميع الوثائق التقنية والمخططات التصميمية مجانية وعلنية</td><td>بلا عتبة؛ يمكن لجميع أشكال الحياة الحصول عليها</td></tr><tr><td>انفتاح مرخص</td><td>التقنيات الناضجة من مستوى R2</td><td>المبادئ الأساسية علنية؛ والتنفيذ الهندسي يتطلب طلب ترخيص</td><td>يجب اجتياز تدريب الأمان الأساسي والتعهد بالامتثال لمعايير الاستخدام</td></tr><tr><td>انفتاح مقيد</td><td>تقنيات مستوى R3</td><td>تُفتح حصرياً لمؤسسات البحث المرخصة، مع توقيع اتفاقيات أمان</td><td>يجب امتلاك فضاء معزول بمستوى S ومؤهلات المراجعة الأخلاقية</td></tr><tr><td>انفتاح محظور</td><td>التقنيات المحظورة من مستوى R4</td><td>لا تُفتح</td><td>منع تام</td></tr></tbody></table><p>بالنسبة للتقنيات مفتوحة الانفتاح الكامل، أسست الحضارة التكافلية «مكتبة القوانين مفتوحة المصدر» — قاعدة معارف تقنية تشبه مجتمعات البرمجيات مفتوحة المصدر في العالم الواقعي. يمكن لجميع المطورين إيداع إنجازاتهم التقنية في المكتبة، التي تفتحها للحضارة كلها بعد مراجعة لجنة التكنولوجيا. تعتمد تقنيات المكتبة «رخصة المشاركة التكافلية»، التي تسمح بالاستخدام والتعديل وإعادة التوزيع بحرية، على أن تُشارك الأعمال المشتقة أيضاً بأسلوب مفتوح المصدر.</p><h2 id="ثالثاً-البنية-التحتية-لتعميم-التكنولوجيا" tabindex="-1">ثالثاً: البنية التحتية لتعميم التكنولوجيا <a class="header-anchor" href="#ثالثاً-البنية-التحتية-لتعميم-التكنولوجيا" aria-label="Permalink to &quot;ثالثاً: البنية التحتية لتعميم التكنولوجيا&quot;">​</a></h2><p>ضماناً لعدم بقاء الانفتاح التكنولوجي شكلياً، بنت الحضارة التكافلية بنية تحتية كاملة لتعميم التكنولوجيا:</p><ol><li><strong>نظام التعليم التقني</strong>: يدرج نظام التعليم التكافلي المعارف الأساسية لهندسة القوانين ضمن محتوى التعليم العام، لضمان أن يمتلك كل شكل من أشكال الحياة القدرة على فهم التقنيات الأساسية وتطبيقها. والتعليم التقني المتقدم مفتوح مجاناً لجميع المتعلمين الراغبين.</li><li><strong>شبكة نشر التكنولوجيا</strong>: بالاعتماد على شبكة الاتصالات عبر الأبعاد، تُنشأ منصة نشر تقنية تشمل الكون كله، تتضمن دورات عبر الإنترنت ومنتديات تقنية ومختبرات افتراضية، ليتمكن متعلمو الأبعاد النائية من الحصول على أحدث المعارف التقنية.</li><li><strong>المرافق التقنية العامة</strong>: تُجهز مراسي المجتمع بمختبرات تقنية عامة ومعدات تصنيع، يمكن لأي شكل من أشكال الحياة حجزها واستخدامها، لتحويل المعرفة التقنية إلى منتجات فعلية.</li><li><strong>نظام المرشدين التقنيين</strong>: يلتزم الكوادر التقنية العليا بالعمل دورياً كمرشدين تقنيين لإرشاد المتعلمين المبتدئين؛ ويُحتسب هذا الالتزام في درجة مساهمتهم التكافلية.</li></ol><h2 id="رابعاً-قياس-الإسهام-التقني-وتحفيزه" tabindex="-1">رابعاً: قياس الإسهام التقني وتحفيزه <a class="header-anchor" href="#رابعاً-قياس-الإسهام-التقني-وتحفيزه" aria-label="Permalink to &quot;رابعاً: قياس الإسهام التقني وتحفيزه&quot;">​</a></h2><p>تعتمد استدامة آلية الانفتاح التكنولوجي على نظام معقول لقياس الإسهامات وتحفيزها:</p><ul><li><strong>قياس الإسهام</strong>: بعد إدراج الإنجازات التقنية التي يودعها المطورون في مكتبة القوانين مفتوحة المصدر، تُحسب «درجة المساهمة التقنية» وفق قيمتها التقنية ونطاق تطبيقها وإسهاماتها المشتقة. ودرجة المساهمة أساس مهم لتوزيع الموارد في آلية التعاقد المشترك على الإنتاج.</li><li><strong>حقوق الاستخدام الأولوية</strong>: يتمتع مطورو التكنولوجيا خلال فترة معينة بحقوق الاستخدام الأولوية لإنجازاتهم التقنية وبأولوية الخدمات المتقدمة، دون أن يحتكروا حق ترخيص التكنولوجيا.</li><li><strong>نظام التكريم</strong>: يُمنح مطورو التكنولوجيا ذوو الإسهامات الكبرى للحضارة أوسمة مثل «وسام التكنولوجيا التكافلية»، وتُسجل إنجازاتهم في تاريخ تكنولوجيا الحضارة.</li><li><strong>المنافع المستمرة</strong>: بالنسبة للتطبيقات التقنية المتقدمة التي تستهلك طاقة كبيرة، يمكن للمطورين الحصول على نسبة معقولة من أرباح التطبيق، على أن تخضع النسبة للسقوف العليا لقانون مكافحة الاحتكار.</li></ul><h2 id="خامساً-مكافحة-الاحتكار-والعدالة-التقنية" tabindex="-1">خامساً: مكافحة الاحتكار والعدالة التقنية <a class="header-anchor" href="#خامساً-مكافحة-الاحتكار-والعدالة-التقنية" aria-label="Permalink to &quot;خامساً: مكافحة الاحتكار والعدالة التقنية&quot;">​</a></h2><p>يُضمن تنفيذ آلية الانفتاح التكنولوجي بصرامة بقانون مكافحة الاحتكار:</p><ul><li>يُمنع على أي منظمة أو فرد احتكار حق ترخيص التقنيات الأساسية عبر حواجز براءات الاختراع أو السرية التقنية أو غيرها من الوسائل.</li><li>يُمنع «الإغلاق التقني»، أي إجبار المستخدمين على الاعتماد على مورّدي تقنيات محددين عبر خلق معايير غير متوافقة عمداً.</li><li>يُطبق الانفتاح الإلزامي على تقنيات البنية التحتية الرئيسية (كعتاد المرساة وتوزيع الطاقة والاتصالات عبر الأبعاد)، ويجب أن تضع الحضارة كلها معاييرها الأساسية بالاشتراك.</li><li>تُنشأ آلية تقييم العدالة التقنية، لتقييم مدى توازن تعميم التكنولوجيا دورياً، وتقديم دعم موجه للأبعاد والجماعات المتأخرة تقنياً.</li></ul><h2 id="سادساً-التوازن-بين-الانفتاح-والأمان-التقنيين" tabindex="-1">سادساً: التوازن بين الانفتاح والأمان التقنيين <a class="header-anchor" href="#سادساً-التوازن-بين-الانفتاح-والأمان-التقنيين" aria-label="Permalink to &quot;سادساً: التوازن بين الانفتاح والأمان التقنيين&quot;">​</a></h2><p>يتطلب الأمر توازناً دقيقاً بين الانفتاح التكنولوجي والأمان التقني. ونهج الحضارة التكافلية هو:</p><ul><li>الانفتاح الكامل للمبادئ الأساسية والمعارف العامة، ليفهم مزيد من الناس جوهر التكنولوجيا وبالتالي يحددوا المخاطر التقنية بشكل أفضل.</li><li>الانفتاح المقيد للمعلمات المحددة وتفاصيل التنفيذ للعمليات عالية الخطورة، فلا تُقدم إلا للمؤسسات المستوفية لشروط الأمان.</li><li>السرية الصارمة لمعارف التقنيات المحظورة، مع بقاء التحليل الأخلاقي لـ«لماذا هي محظورة» علنياً وشفافاً، لتفهم الحضارة كلها معنى وجود الحدود.</li><li>وضع مدونة «النشر المسؤول للتكنولوجيا»، يلتزم بموجبها ناشرو التكنولوجيا بنشر طرق الاستخدام الآمن والحدود الأخلاقية في الوقت ذاته.</li></ul><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>إن آلية الانفتاح التكنولوجي والمشاركة إحدى السمات الرئيسية التي تميز حضارة التكافل المرساة عن الحضارات الافتراسية. ففي النظام الافتراسي، التكنولوجيا أداة الأقوياء لقمع الضعفاء؛ وفي الحضارة التكافلية، التكنولوجيا سلم للتطور المشترك لعشرة آلاف عرق. ومن خلال الانفتاح المتدرج والبنية التحتية للتعميم والحوافز المعقولة وضمانات مكافحة الاحتكار، تبني الحضارة التكافلية نظاماً تقنياً قوامه «تدفق حر للمعرفة، وارتفاع عام للقدرات، ومكافأة عادلة للإسهامات»، يوفر طاقة ابتكارية لا تنضب للارتقاء البعدي للحضارة ككل.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>60-技术体系总览 (نظرة عامة على النظام التكنولوجي)</li><li>68-技术伦理与安全边界 (أخلاقيات التكنولوجيا وحدود الأمان)</li><li>47-反垄断法 (قانون مكافحة الاحتكار)</li></ul>',25)])])}const p=a(e,[["render",i]]);export{u as __pageData,p as default};
